  passwordInput(): void {
    const loginData = this.loginForm.value;
    if (!this.username) {
      return;
    }
    const name = this.username;
    const password = loginData.pw ?? '';
    this.problemText = '';
    this.problemCode = 0;

    if (!this.mainDataService.appConfig?.bruteForceProtection.includes('login')) {
      this.backendService.login(name, password).subscribe(this.getLoginSubscription());
      return;
    }

    this.user = 'sync';
    this.backendService.createChallenge({ loginType: 'login', name, password }).subscribe({
      next: challenge => {
        (this.altchaLib ??= import('altcha-lib')).then(({ solveChallengeWorkers }) => solveChallengeWorkers(
          `${window.document.baseURI}/altcha-lib/dist/worker.js`,
          8,
          challenge.challenge,
          challenge.salt,
          challenge.algorithm,
          challenge.maxNumber
        )).then(solvedChallenge => {
          if (!solvedChallenge) {
            this.problemText = 'Problem bei der Anmeldung.';
            return;
          }
          this.backendService.createSession(
            challenge.algorithm,
            challenge.challenge,
            challenge.salt,
            challenge.signature,
            solvedChallenge.number
          ).subscribe(this.getLoginSubscription());
        }, error => {
          this.problemText = 'Problem bei der Anmeldung.';
          throw error;
        }).finally(() => {
          this.user = 'school';
        });
      },
      error: error => {
        this.problemText = 'Problem bei der Anmeldung.';
        this.user = 'school';
        throw error;
      }
    });
  }

  private getLoginSubscription(): Partial<Observer<AuthData>> {
    this.inputType = authData?.viewSettings.codeInput?.type || 'text-field';
    this.length = authData?.viewSettings.codeInput?.length;
    this.assetService.assetSlots$.subscribe(() => {
      this.illustrationImageSrc = this.assetService.getAssetSrc('codeInputIllustration');
    });
  }

  ngOnInit(): void {
    if (this.mds.appConfig?.bruteForceProtection.includes('person')) {
      this.altchaLib = import('altcha-lib');
    }
  }

  protected onSubmit(code: string) {
    if (!code) return;
    this.loading = true;
    this.problemText = '';
    this.problemCode = 0;

    if (this.mds.appConfig?.bruteForceProtection.includes('person')) {
      this.bs.createChallenge({ code }).subscribe({
        next: challenge => {
          (this.altchaLib ??= import('altcha-lib')).then(({ solveChallengeWorkers }) => solveChallengeWorkers(
            `${window.document.baseURI}/altcha-lib/dist/worker.js`,
            8,
            challenge.challenge,
            challenge.salt,
            challenge.algorithm,
            challenge.maxNumber
          )).then(solvedChallenge => {
            if (!solvedChallenge) {
              this.problemText = 'Problem bei der Anmeldung.';
              this.loading = false;
              return;
            }
            this.bs.createSession(
              challenge.algorithm,
              challenge.challenge,
              challenge.salt,
              challenge.signature,
              solvedChallenge.number
            ).subscribe(this.codeSubscription);
          }, error => {
            this.problemText = 'Problem bei der Anmeldung.';
            this.loading = false;
            throw error;
          });
        },
        error: error => {
          this.problemText = 'Problem bei der Anmeldung.';
          this.loading = false;
          throw error;
        }
      });
      return;
    }
