export class AdminLoginComponent implements OnInit, OnDestroy {
  static oldLoginName = '';
  problemText = '';
  problemLevel: 'error' | 'warning' = 'error';
  problemCode = 0;
  showPassword = false;
  admin = 'person';
  unsupportedBrowser: [string, string] | [] = [];
  private altchaLib?: Promise<typeof import('altcha-lib')>;

  loginForm = new FormGroup({
    name: new FormControl(AdminLoginComponent.oldLoginName, [Validators.required, Validators.minLength(3)]),
    pw: new FormControl('', [Validators.required])
  });

  constructor(public mainDataService: MainDataService, private headerService: HeaderService,
              private backendService: BackendService, private router: Router, private footerService: FooterService) { }

  ngOnInit(): void {
    if (this.mainDataService.appConfig?.bruteForceProtection.includes('admin')) {
      this.altchaLib = import('altcha-lib');
    }
    this.headerService.title = 'Anmelden';
    this.checkBrowser();
    this.footerService.showFooter.set(true);
  }

  ngOnDestroy(): void {
    this.footerService.showFooter.set(false);
  }

  adminLogin(): void {
    const loginData = this.loginForm.value;
    if (!loginData.name || !loginData.pw) {
      return;
    }
    const name = loginData.name;
    const password = loginData.pw;
    AdminLoginComponent.oldLoginName = name;
    this.problemText = '';
    this.problemCode = 0;

    if (!this.mainDataService.appConfig?.bruteForceProtection.includes('admin')) {
      this.backendService.adminLogin(name, password).subscribe(this.getAdminLoginSubscription());
      return;
    }

    this.admin = 'sync';
    this.backendService.createChallenge({ loginType: 'admin', name, password }).subscribe({
      next: challenge => {
        solveChallengeWorkers(
          `${window.document.baseURI}/altcha-lib/dist/worker.js`,
          8,
          challenge.challenge,
          challenge.salt,
          challenge.algorithm,
          challenge.maxNumber
        ).then(solvedChallenge => {
          if (!solvedChallenge) {
            this.problemText = 'Problem bei der Anmeldung.';
            return;
          }
          this.backendService.createSession(
            challenge.algorithm,
            challenge.challenge,
            challenge.salt,
            challenge.signature,
            solvedChallenge.number
          ).subscribe(this.getAdminLoginSubscription());
        }, error => {
          this.problemText = 'Problem bei der Anmeldung.';
          throw error;
        }).finally(() => {
          this.admin = 'person';
        });
      },
      error: error => {
        this.problemText = 'Problem bei der Anmeldung.';
        this.admin = 'person';
        throw error;
      }
    });
  }

  private getAdminLoginSubscription(): Partial<Observer<AuthData>> {
    return {
      next: authData => {
        this.mainDataService.setAuthData(authData);
        this.router.navigate(['/r/starter']);
      },
      error: error => {
        this.admin = 'person';
        this.problemCode = error.code;
        if (error.code === 400) {
          this.problemText = 'Anmeldedaten sind nicht gültig. Bitte noch einmal versuchen!';
        } else if (error.code === 401) {
          this.problemText = 'Anmeldung abgelehnt. Anmeldedaten sind noch nicht freigeben.';
        } else if (error.code === 204) {
          this.problemText = 'Anmeldedaten sind gültig, aber es sind keine Arbeitsbereiche oder Tests freigegeben.';
        } else if (error.code === 410) {
          this.problemText = 'Anmeldedaten sind abgelaufen';
        } else if (error.code === 429) {
          this.problemText = 'Zu viele Fehlversuche! Probieren Sie es zu einem späteren Zeitpunkt noch einmal.';
        } else {
          this.problemText = 'Problem bei der Anmeldung.';
          throw error;
        }
        this.problemLevel = 'error';
        this.loginForm.reset();
      }
    };
  }

  checkCapsLock(event: KeyboardEvent): void {
    // some newer edge versions does fire a keyup event when clicking into the textfield, which does not
    // have getModifierState TODO find the route cause of this instead of workaround
    if (typeof event.getModifierState !== 'function') return;
    if (event.getModifierState('CapsLock')) {
      this.problemText = 'Feststelltaste ist aktiviert!';
      this.problemLevel = 'warning';
    }
  }

  clearWarning(): void {
    this.problemText = '';
    this.problemLevel = 'error';
    this.problemCode = 0;
  }

  private checkBrowser() {
    const ua = UserAgentService.resolveUserAgent();
    if (!UserAgentService.userAgentMatches(ua)) {
      this.unsupportedBrowser = [ua.family, ua.version];
    }
  }
}
import { Inject, Injectable } from '@angular/core';
import {
  BehaviorSubject, Observable, ReplaySubject, Subject
} from 'rxjs';
import { ActivatedRoute, Router } from '@angular/router';
import { distinct } from 'rxjs/internal/operators/distinct';
import { shareReplay } from 'rxjs/internal/operators/shareReplay';
import { filter } from 'rxjs/operators';
import { CustomtextService } from '../customtext/customtext.service';
import {
  AccessObject, AppError, AuthAccessType, AuthData
} from '../../../app.interfaces';
import { AppConfig } from '../../classes/app.config';
import { BackendService } from '../backend.service';
import { SysStatus } from '../../interfaces/service-status.interfaces';

const localStorageAuthDataKey = 'iqb-tc-a';

@Injectable({
  providedIn: 'root'
})
export class MainDataService {
  private _appError$ = new ReplaySubject<AppError | void>(0);
  get appError$(): Observable<AppError> {
    return this._appError$
      .pipe(
        filter((v: AppError | void): v is AppError => v !== undefined),
        distinct(error => (error?.stack ?? '') + (error?.errorId ?? '')),
        shareReplay(0)
      );
  }

  set appError(error: AppError) {
    this._appError$.next(error);
  }

  private _authData$ = new BehaviorSubject<AuthData | null>(null);
  get authData$(): Observable<AuthData | null> {
    return this._authData$.asObservable();
  }

  private _appConfig$ = new BehaviorSubject<AppConfig | null>(null);
  // TODO remove this function everywhere and replace with appConfig$ and wait unit it's there to avoid race conditions
  get appConfig(): AppConfig | null {
    return this._appConfig$.getValue();
  }

  get appConfig$(): Observable<AppConfig> {
    return this._appConfig$
      .pipe(filter((v): v is AppConfig => v instanceof AppConfig));
  }

  set appConfig$(appConfig: AppConfig) {
    this._appConfig$.next(appConfig);
  }

  sysStatus: SysStatus = {
    fileService: 'unknown',
    broadcastingService: 'unknown',
    cacheService: 'unknown'
  };

  sysCheckAvailableForAll = false;
  appTitle$ = new BehaviorSubject<string>('IQB-Testcenter');
  appSubTitle$ = new BehaviorSubject<string>('');
  globalWarning = '';

  postMessage$ = new Subject<MessageEvent>();
  appWindowHasFocus$ = new Subject<boolean>();
  isFullScreen: boolean = false;

  isExtendedKbUsed: boolean | null = null;

  isTestingMode: boolean = false;

  getAuthData(): AuthData | null {
    if (this._authData$.getValue()) {
      return this._authData$.getValue();
    }
    try {
      const entry = localStorage.getItem(localStorageAuthDataKey);
      if (!entry) {
        return null;
      }
      return JSON.parse(entry);
    } catch (e) {
      return null;
    }
  }

  getAccessObject(type: AuthAccessType, id: string): AccessObject {
    const authData = this.getAuthData();
    if (!authData) {
      throw new AppError({ type: 'session', description: '', label: 'Nicht angemeldet' });
    }
    const claim = authData.claims[type].find(accessObject => accessObject.id === id);
    if (!claim) {
      throw new AppError({ type: 'session', description: '', label: `${type} ${id} nicht freigegeben.` });
    }
    return claim;
  }

  constructor(
    private cts: CustomtextService,
    private bs: BackendService,
    private router: Router,
    private route: ActivatedRoute,
    @Inject('IS_PRODUCTION_MODE') public isProductionMode: boolean
  ) {
    this.appConfig$.subscribe(appConfig => {
      this.appTitle$.next(appConfig.appTitle);
      this.globalWarning = appConfig.getWarningMessage();
      const authData = this.getAuthData();
      if (authData) {
        this.cts.addCustomTexts(authData.customTexts);
      }
    });
    this.getTestMode();
  }

  setAuthData(authData: AuthData): void {
    this._authData$.next(authData);
    if (this.appConfig?.customTexts) {
      this.cts.addCustomTexts(this.appConfig.customTexts);
    }
    if (authData.customTexts) {
      this.cts.addCustomTexts(authData.customTexts);
    }
    localStorage.setItem(localStorageAuthDataKey, JSON.stringify(authData));
  }

  logOut(): void {
    this.cts.restoreDefault(true);
    this.bs.deleteSession()
      .subscribe(() => {
        this.quit();
      });
  }

  quit(): void {
    this._authData$.next(null);
    localStorage.removeItem(localStorageAuthDataKey);
    window.location.href = '/';
  }

  resetAuthData(): void {
    const storageEntry = localStorage.getItem(localStorageAuthDataKey);
    if (storageEntry) {
      localStorage.removeItem(localStorageAuthDataKey);
    }
    this._authData$.next(this.getAuthData());
  }

  reloadPage(logOut: boolean = false): void {
    if (logOut) {
      this._authData$.next(null);
      localStorage.removeItem(localStorageAuthDataKey);
    }
